using Gtk 4.0;
using Adw 1;

template $GcalCalendarList: Adw.Bin {
  child: ScrolledWindow {
    hscrollbar-policy: never;
    propagate-natural-height: true;
    propagate-natural-width: true;

    child: Adw.Clamp {
      maximum-size: 800;
      tightening-threshold: 800;

      child: ListBox calendar_listbox {
        hexpand: true;
        selection-mode: none;
        row-activated => $on_listbox_row_activated_cb(template) not-swapped;
        // Allow Page-Up/Page-Down to consistently switch months/weeks,
        // regardless of whether the sidebar's calendars listbox has focus.
        ShortcutController {
          propagation-phase: capture;

          Shortcut {
            trigger: "Page_Up";
            action: "action(win.previous-date)";
          }

          Shortcut {
            trigger: "Page_Down";
            action: "action(win.next-date)";
          }
        }

        styles [
          "navigation-sidebar",
          "calendar-list",
        ]
      };
    };
  };
}

using Gtk 4.0;
using Adw 1;

template $GcalCalendarNavigationButton: Adw.Bin {
  child: Stack stack {
    hhomogeneous: false;

    StackPage {
      name: "active";

      child: MenuButton button {
        popover: popover_date_chooser;
        label: _("_Choose Date");
        use-underline: true;
        can-shrink: true;
        tooltip-text: _("Choose a Date");
        always-show-arrow: true;
      };
    }

    StackPage {
      name: "inactive";

      child: Label static_label {
        styles [
          "heading",
        ]

        label: bind button.label no-sync-create;
        margin-start: 9;
        margin-end: 9;
      };
    }

    visible-child-name: "active";
  };
}

Popover popover_date_chooser {
  position: bottom;

  child: $GcalDateChooser {
    split-month-year: true;
    vexpand: false;
    valign: end;
    active-date: bind template.active-date no-sync-create bidirectional;
  };
}

using Gtk 4.0;
using Adw 1;

template $GcalEventPopover: Popover {
  default-widget: action_button;
  position: top;
  width-request: 250;

  styles [
    "event-popover",
  ]

  child: Adw.Clamp clamp {
    maximum-size: 400;
    tightening-threshold: bind clamp.maximum-size;

    child: Box {
      orientation: vertical;

      Box {
        spacing: 18;
        margin-top: 18;
        margin-bottom: 12;
        margin-start: 18;
        margin-end: 18;

        Box {
          hexpand: true;
          orientation: vertical;
          spacing: 6;

          Label summary_label {
            selectable: true;
            wrap: true;
            wrap-mode: word_char;
            xalign: 0.0;
            lines: 6;
            ellipsize: end;

            styles [
              "title-4",
            ]
          }

          Label date_time_label {
            xalign: 0.0;

            styles [
              "dimmed",
            ]
          }
        }

        Box {
          spacing: 6;

          Image read_only_icon {
            tooltip-markup: _(
              "<b>This event is part of a read-only calendar</b>\n    You cannot delete or change this event."
            );
            icon-name: "changes-prevent-symbolic";
            pixel-size: 18;
            valign: start;
            halign: end;
            margin-top: 8;
            margin-bottom: 8;

            styles [
              "dimmed",
            ]
          }

          Button ics_export_button {
            valign: start;
            halign: end;
            icon-name: "share-symbolic";
            tooltip-text: _("Export Event");

            styles [
              "circular",
            ]

            clicked => $on_ics_export_button_clicked_cb(template) not-swapped;
          }

          Button action_button {
            can-focus: true;
            valign: start;
            halign: end;

            styles [
              "circular",
            ]

            clicked => $on_action_button_clicked_cb(template) not-swapped;
          }
        }
      }

      Separator {}

      Label placeholder_label {
        vexpand: true;
        label: _("No event notes");
        margin-top: 12;
        margin-bottom: 12;
        use-markup: true;

        styles [
          "dimmed",
          "no-events",
        ]
      }

      ScrolledWindow description_scrolled_window {
        hscrollbar-policy: never;
        propagate-natural-height: true;
        propagate-natural-width: true;
        max-content-height: 350;

        child: Label description_label {
          use-markup: true;
          selectable: true;
          halign: fill;
          xalign: 0.0;
          wrap: true;
          wrap-mode: word_char;
          margin-top: 12;
          margin-bottom: 18;
          margin-start: 18;
          margin-end: 18;
        };
      }

      Box location_box {
        orientation: vertical;

        Separator {}

        Box {
          margin-top: 12;
          margin-bottom: 12;
          margin-start: 18;
          margin-end: 18;
          spacing: 12;

          Box {
            orientation: vertical;

            Label {
              halign: start;
              label: _("Location");

              styles [
                "heading",
              ]
            }

            Label location_label {
              halign: start;
              selectable: true;
              ellipsize: end;
            }
          }

          Button {
            halign: end;
            hexpand: true;
            valign: center;
            tooltip-text: _("Open Location");
            icon-name: "map-symbolic";

            styles [
              "circular",
            ]

            clicked => $on_map_button_clicked_cb(template) not-swapped;
          }
        }
      }

      Box meetings_box {
        orientation: vertical;
        visible: false;

        Separator {}

        ListBox meetings_listbox {
          selection-mode: none;
          margin-top: 12;
          margin-bottom: 12;
          margin-start: 18;
          margin-end: 18;

          styles [
            "calendar-list",
          ]
        }
      }
    };
  };
}

using Gtk 4.0;
using Adw 1;

template $GcalEventWidget: Widget {
  focusable: true;
  overflow: hidden;
  receives-default: true;

  accessibility {
    has-popup: true;
  }

  DragSource drag_source {
    propagation-phase: bind $read_only_to_propagation_phase_cb(
      template.event as <$GcalEvent>.calendar as <$GcalCalendar>.read-only
      );
    prepare => $on_drag_source_prepare_cb(template) not-swapped;
    begin => $on_drag_source_begin_cb(template) not-swapped;
  }

  GestureClick {
    pressed => $on_click_gesture_pressed_cb(template) not-swapped;
    released => $on_click_gesture_release_cb(template) not-swapped;
  }

  Adw.Bin edge {
    styles [
      "edge",
    ]
  }

  $GcalOverflowBin overflow_bin {
    hexpand: true;
    request-mode: width-for-height;

    styles [
      "content",
    ]

    Box vertical_box {
      orientation: vertical;

      $GcalOverflowBin {
        request-mode: width-for-height;

        Label {
          label: bind timestamp_label.label no-sync-create;
          xalign: 0.0;

          styles [
            "dimmed",
          ]
        }
      }

      Inscription {
        text: bind summary_label.text;
        hexpand: true;
        vexpand: true;
        xalign: 0.0;
        yalign: 0.0;
        min-lines: 1;
        text-overflow: ellipsize_end;
      }
    }

    Box horizontal_box {
      spacing: 4;

      $GcalFadingLabel summary_label {
        text: bind template.event as <$GcalEvent>.summary;
        hexpand: true;
        vexpand: true;
      }

      Label timestamp_label {
        halign: end;

        styles [
          "dimmed",
        ]
      }
    }
  }
}

using Gtk 4.0;

template $GcalMeetingRow: ListBoxRow {
  activatable: false;
  selectable: false;

  child: Box {
    spacing: 6;

    Box {
      orientation: vertical;
      hexpand: true;

      Label title {
        halign: start;

        styles [
          "heading",
        ]
      }

      Label subtitle {
        halign: start;
        single-line-mode: true;
        ellipsize: end;
      }
    }

    Button join_button {
      halign: end;
      valign: center;
      margin-start: 12;
      use-underline: true;
      label: _("_Join");

      styles [
        "suggested-action",
      ]

      clicked => $on_join_button_clicked_cb(template) not-swapped;
    }
  };
}

using Gtk 4.0;
using Adw 1;

template $GcalQuickAddPopover: Popover {
  show => $gtk_widget_grab_focus(summary_entry);
  width-request: 360;

  styles [
    "quick-add-popover",
  ]

  child: Box {
    orientation: vertical;
    margin-top: 12;
    margin-bottom: 12;
    spacing: 12;

    Label title_label {
      hexpand: true;
      wrap: true;
      max-width-chars: 25;
      xalign: 0.0;
      margin-top: 6;
      margin-bottom: 6;
      margin-start: 27;
      margin-end: 27;

      styles [
        "title-4",
      ]
    }

    ListBox {
      accessible-role: none;
      selection-mode: none;
      margin-start: 12;
      margin-end: 12;

      styles [
        "boxed-list",
      ]

      Adw.EntryRow summary_entry {
        title: _("Title");
        notify::text => $summary_entry_text_changed(template) not-swapped;
        entry-activated => $summary_entry_activated(template) not-swapped;
      }
    }

    ScrolledWindow {
      propagate-natural-height: true;
      max-content-height: 240;

      styles [
        "undershoot-top",
        "undershoot-bottom",
      ]

      child: ListBox calendars_list_box {
        tab-behavior: item;
        margin-start: 12;
        margin-end: 12;
        margin-top: 12;
        margin-bottom: 12;
        row-selected => $row_selected_cb(template);

        styles [
          "boxed-list",
          "calendars-list",
          "compact",
        ]
      };
    }

    Box {
      homogeneous: true;
      margin-start: 12;
      margin-end: 12;
      spacing: 9;

      Button edit_button {
        valign: center;
        clicked => $edit_or_create_event(template);

        child: Label {
          label: _("_Edit Details");
          use-underline: true;

          styles [
            "heading",
          ]
        };
      }

      Button add_button {
        valign: center;
        sensitive: false;
        label: _("_Save Event");
        use-underline: true;
        clicked => $edit_or_create_event(template);

        styles [
          "suggested-action",
        ]
      }
    }
  };
}

using Gtk 4.0;
using Adw 1;

template $GcalSearchButton: Adw.Bin {
  EventControllerFocus {
    leave => $on_focus_controller_leave_cb(template) not-swapped;
  }

  Stack stack {
    hhomogeneous: false;
    vhomogeneous: true;
    interpolate-size: true;
    transition-type: crossfade;
    transition-duration: 200;

    styles [
      "suggestionbutton",
    ]

    StackPage {
      name: "button";

      child: Button button {
        halign: start;
        icon-name: "edit-find-symbolic";
        tooltip-text: _("Search Events");
        clicked => $on_button_clicked_cb(template) not-swapped;

        ShortcutController {
          scope: global;

          Shortcut {
            trigger: "<Control>f";
            action: "activate";
          }
        }
      };
    }

    StackPage {
      name: "entry";

      child: SearchEntry entry {
        placeholder-text: _("Search events");
        max-width-chars: 0;
        width-chars: 0;
        search-delay: 500;
        activate => $on_entry_activate_cb(template) not-swapped;
        next-match => $on_entry_next_match_cb(template) not-swapped;
        previous-match => $on_entry_previous_match_cb(template) not-swapped;
        search-changed => $on_entry_search_changed_cb(template) not-swapped;
        stop-search => $on_entry_stop_search_cb(template) not-swapped;

        accessibility {
          labelled-by: [
            entry,
          ];
        }

        ShortcutController {
          Shortcut {
            trigger: "Up";
            action: "signal(previous-match)";
          }

          Shortcut {
            trigger: "Down";
            action: "signal(next-match)";
          }
        }
      };
    }
  }
}

Popover popover {
  position: bottom;
  autohide: false;
  default-widget: results_listview;

  styles [
    "menu",
  ]

  Revealer results_revealer {
    transition-type: slide_down;
    notify::reveal-child => $on_results_revealer_child_reveal_state_changed_cb(template) not-swapped;
    notify::child-revealed => $on_results_revealer_child_reveal_state_changed_cb(template) not-swapped;

    ScrolledWindow {
      max-content-width: 450;
      max-content-height: 400;
      propagate-natural-width: true;
      propagate-natural-height: true;
      hscrollbar-policy: never;

      ListView results_listview {
        hscroll-policy: natural;
        vscroll-policy: natural;
        single-click-activate: true;

        model: SingleSelection results_selection_model {
          autoselect: true;
          can-unselect: false;
        };

        factory: BuilderListItemFactory {
          template ListItem {
            activatable: true;
            selectable: true;

            child: Box {
              Image image {
                valign: center;
                hexpand: false;
                icon-size: normal;
                paintable: bind template.item as <$GcalSearchHit>.primary-icon;

                accessibility {
                  labelled-by: [
                    title,
                  ];
                }

                styles [
                  "title",
                ]
              }

              Label title {
                use-markup: true;
                ellipsize: end;
                xalign: 0.0;
                max-width-chars: 40;
                label: bind $escape_markup_cb(template.item as <$GcalSearchHit>.title);
              }

              Label separator {
                label: "—";
                visible: bind $string_is_not_empty_cb(template.item as <$GcalSearchHit>.subtitle);

                styles [
                  "dimmed",
                ]
              }

              Label subtitle {
                hexpand: true;
                use-markup: true;
                ellipsize: end;
                xalign: 0.0;
                label: bind $escape_markup_cb(template.item as <$GcalSearchHit>.subtitle);

                styles [
                  "subtitle",
                ]
              }
            };
          }
        };

        activate => $on_results_listview_activated_cb(template) not-swapped;
      }
    }
  }
}

using Gtk 4.0;
using Adw 1;

template $GcalSyncIndicator: Adw.Bin {
  child: Stack stack {
    transition-type: crossfade;
    transition-duration: 250;

    StackPage {
      name: "empty";

      child: Box {};
    }

    StackPage {
      name: "spinner";

      child: Adw.Spinner refreshing_spinner {
        tooltip-text: C_("tooltip", "Synchronizing Remote Calendars");
      };
    }

    StackPage {
      name: "success";

      child: Image success_image {
        icon-name: "checkmark-small-symbolic";
      };
    }
  };
}

using Gtk 4.0;

template $GcalWeatherSettings: Box {
  orientation: vertical;
  margin-top: 12;
  margin-bottom: 12;
  margin-start: 12;
  margin-end: 12;
  spacing: 6;

  Box {
    spacing: 18;

    Label {
      hexpand: true;
      xalign: 0.0;
      label: _("Show Weather");
    }

    Switch show_weather_switch {
      notify::active => $on_show_weather_changed_cb(template) not-swapped;
    }
  }

  Box weather_auto_location_box {
    spacing: 18;

    Label {
      hexpand: true;
      xalign: 0.0;
      label: _("Automatic Location");
    }

    Switch weather_auto_location_switch {
      notify::active => $on_weather_auto_location_changed_cb(template) not-swapped;
    }
  }

  Entry weather_location_entry {
    placeholder-text: _("Search locations");
    primary-icon-name: "edit-find-symbolic";
    primary-icon-activatable: false;
    primary-icon-sensitive: false;
    changed => $on_weather_location_searchbox_changed_cb(template) not-swapped;
    activate => $on_weather_location_searchbox_changed_cb(template) not-swapped;
  }
}

using Gtk 4.0;
using Adw 1;

template $GcalWindow: Adw.ApplicationWindow {
  title: _("Calendar");
  default-width: 800;
  default-height: 600;
  width-request: 360;
  height-request: 600;

  ShortcutController {
    Shortcut {
      trigger: "<Control>t";
      action: "action(win.today)";
    }

    Shortcut {
      trigger: "<Alt>Down";
      action: "action(win.today)";
    }

    Shortcut {
      trigger: "Home";
      action: "action(win.today)";
    }

    Shortcut {
      trigger: "<Alt>Left";
      action: "action(win.previous-date)";
    }

    Shortcut {
      trigger: "Page_Up";
      action: "action(win.previous-date)";
    }

    Shortcut {
      trigger: "<Alt>Right";
      action: "action(win.next-date)";
    }

    Shortcut {
      trigger: "Page_Down";
      action: "action(win.next-date)";
    }

    Shortcut {
      trigger: "<Control>Page_Down";
      action: "action(win.change-view)";
      arguments: "-1";
    }

    Shortcut {
      trigger: "<Control>Page_Up";
      action: "action(win.change-view)";
      arguments: "-2";
    }

    Shortcut {
      trigger: "<Alt>1";
      action: "action(win.change-view)";
      arguments: "0";
    }

    Shortcut {
      trigger: "<Alt>2";
      action: "action(win.change-view)";
      arguments: "1";
    }

    Shortcut {
      trigger: "<Alt>3";
      action: "action(win.change-view)";
      arguments: "3";
    }

    Shortcut {
      trigger: "<Ctrl>n";
      action: "action(win.new-event)";
    }

    Shortcut {
      trigger: "<Control>w";
      action: "action(window.close)";
    }

    Shortcut {
      trigger: "<Control>q";
      action: "action(app.quit)";
    }

    Shortcut {
      trigger: "<Ctrl><Alt>m";
      action: "action(win.show-calendars)";
    }

    Shortcut {
      trigger: "<Ctrl>r";
      action: "action(app.sync)";
    }

    Shortcut {
      trigger: "F5";
      action: "action(app.sync)";
    }

    Shortcut {
      trigger: "F8";
      action: "action(win.show-calendars)";
    }
  }

  GestureClick {
    button: 8; // Hardware back button.
    pressed => $on_back_button_pressed_cb(template) not-swapped;
  }

  GestureClick {
    button: 9; // Hardware forward button.
    pressed => $on_forward_button_pressed_cb(template) not-swapped;
  }

  Adw.ToastOverlay overlay {
    $GcalDropOverlay drop_overlay {
      overlayed: Adw.StatusPage drop_status_page {
        title: _("Drop Event Files to Import");
        icon-name: "calendar-month-symbolic";

        styles [
          "drop-overlay-area",
          "compact",
        ]
      };

      child: Adw.OverlaySplitView split_view {
        pin-sidebar: true;
        show-sidebar: false;

        DropTarget drop_target {
          actions: copy;
          propagation-phase: capture;
          accept => $on_drop_target_accept_cb(template) not-swapped;
          drop => $on_drop_target_drop_cb(template) not-swapped;
        }

        styles [
          "drop-target",
        ]

        sidebar: Adw.ToolbarView {
          [top]
          Adw.HeaderBar {}

          content: Box {
            orientation: vertical;

            $GcalDateChooser date_chooser {
              split-month-year: true;
              vexpand: false;
              active-date: bind template.active-date no-sync-create bidirectional;
              day-selected => $day_selected(template);
            }

            $GcalCalendarList calendars_list {}
          };
        };

        content: Adw.ToolbarView main_toolbar {
          styles [
            "view",
          ]

          [top]
          Adw.HeaderBar header_bar {
            [start]
            ToggleButton sidebar_button {
              icon-name: "sidebar-show-symbolic";
              tooltip-text: _("Toggle Sidebar");
              active: bind split_view.show-sidebar bidirectional;

              ShortcutController {
                scope: managed;

                Shortcut {
                  trigger: "F9";
                  action: "activate";
                }
              }
            }

            [start]
            $GcalSyncIndicator sync_indicator {}

            title-widget: $GcalCalendarNavigationButton navigation_button_title {
              active-date: bind template.active-date no-sync-create bidirectional;
              active: bind split_view.show-sidebar inverted;
            };

            [end]
            MenuButton menu_button {
              icon-name: "open-menu-symbolic";
              popover: win_menu;
              tooltip-text: _("Main Menu");
              primary: true;
            }

            [end]
            $GcalSearchButton search_button {
              tooltip-text: C_("tooltip", "Search");
            }
          }

          content: Adw.ViewStack views_stack {
            hexpand: true;
            vexpand: true;
            notify::visible-child => $view_changed(template) not-swapped;

            styles [
              "view",
            ]

            Adw.ViewStackPage month_page {
              name: "month";
              title: _("_Month");
              use-underline: true;
              icon-name: "calendar-month-symbolic";

              child: $GcalMonthView month_view {
                active-date: bind template.active-date no-sync-create bidirectional;
                create-event => $show_new_event_widget(template) not-swapped;
                create-event-detailed => $create_event_detailed_cb(template) not-swapped;
                event-activated => $event_activated(template) not-swapped;
              };
            }

            Adw.ViewStackPage week_page {
              name: "week";
              title: _("_Week");
              use-underline: true;
              icon-name: "calendar-week-symbolic";

              child: $GcalWeekView week_view {
                active-date: bind template.active-date no-sync-create bidirectional;
                create-event => $show_new_event_widget(template) not-swapped;
                event-activated => $event_activated(template) not-swapped;
              };
            }

            Adw.ViewStackPage agenda_page {
              name: "agenda";
              title: _("_Agenda");
              use-underline: true;
              icon-name: "calendar-agenda-symbolic";
              visible: false;

              child: $GcalAgendaView agenda_view {
                vexpand: true;
                active-date: bind template.active-date no-sync-create bidirectional;
                create-event => $show_new_event_widget(template) not-swapped;
                event-activated => $event_activated(template) not-swapped;
              };
            }
          };

          [bottom]
          ActionBar {
            [start]
            Button previous_date_button {
              icon-name: bind $get_previous_date_icon(views_stack.visible-child);
              tooltip-text: bind $get_previous_date_tooltip(views_stack.visible-child-name);
              action-name: "win.previous-date";
            }

            [start]
            Button next_date_button {
              icon-name: bind $get_next_date_icon(views_stack.visible-child);
              tooltip-text: bind $get_next_date_tooltip(views_stack.visible-child-name);
              action-name: "win.next-date";
            }

            [start]
            Button {
              action-name: "win.today";

              child: Adw.ButtonContent {
                label: _("_Today");
                use-underline: true;
                icon-name: "calendar-today-symbolic";
                can-shrink: true;
                tooltip-text: _("Go to Today");
              };
            }

            [center]
            Adw.Bin view_switcher_bin {
              child: Adw.ViewSwitcher view_switcher_wide {
                stack: views_stack;
                policy: wide;
              };
            }

            [end]
            Button {
              icon-name: "list-add-symbolic";
              action-name: "win.new-event";
              tooltip-text: C_("tooltip", "Add Event");
            }

            [end]
            Button {
              icon-name: "x-office-calendar-symbolic";
              tooltip-text: _("Manage Calendars");
              action-name: "win.show-calendars";
            }
          }
        };
      };
    }
  }

  notify::current-breakpoint => $on_breakpoint_changed(template) not-swapped;

  Adw.Breakpoint {
    condition ("max-width: 1000sp")

    setters {
      split_view.collapsed: true;
      view_switcher_bin.child: view_switcher_narrow;
    }
  }

  Adw.Breakpoint {
    condition ("max-width: 700sp")

